October 19, 2021 | https://blog.lambda.cx/posts/how-bsd-authentication-works/ | <a href="https://web.archive.org/web/*/https://blog.lambda.cx/posts/how-bsd-authentication-works/">archive.org</a>
<br/><!-- hnss:readable-content --><hr/><div id="readability-page-1" class="page"><div id="outline-text-auth_call">
<details> <summary>
<div>
<div><pre><code data-lang="c"><span>int</span> auth_call(auth_session_t <span>*</span>as, <span>char</span> <span>*</span>path, ...)</code></pre></div>
</div>
</summary>
<div>
<div><pre><code data-lang="c">{
    <span>char</span> <span>*</span>line;
    <span>struct</span> authdata <span>*</span>data;
    <span>struct</span> authopts <span>*</span>opt;
    pid_t pid;
    <span>int</span> status;
    <span>int</span> okay;
    <span>int</span> pfd[<span>2</span>];
    <span>int</span> argc;
    <span>char</span> <span>*</span>argv[<span>64</span>];		<span>/* 64 args should be more than enough */</span>
<span>#define	Nargc	(sizeof(argv)/sizeof(argv[0]))
</span><span></span>
    va_start(as<span>-&gt;</span>ap0, path);

    argc <span>=</span> <span>0</span>;
    <span>if</span> ((argv[argc] <span>=</span> _auth_next_arg(as)) <span>!=</span> NULL)
        <span>++</span>argc;

    <span>if</span> (as<span>-&gt;</span>fd <span>!=</span> <span>-</span><span>1</span>) {
        argv[argc<span>++</span>] <span>=</span> <span>"-v"</span>;
        argv[argc<span>++</span>] <span>=</span> <span>"fd=4"</span>;		<span>/* AUTH_FD, see below */</span>
    }
    <span>/* XXX - fail if out of space in argv */</span>
    <span>for</span> (opt <span>=</span> as<span>-&gt;</span>optlist; opt <span>!=</span> NULL; opt <span>=</span> opt<span>-&gt;</span>next) {
        <span>if</span> (argc <span>&lt;</span> Nargc <span>-</span> <span>2</span>) {
            argv[argc<span>++</span>] <span>=</span> <span>"-v"</span>;
            argv[argc<span>++</span>] <span>=</span> opt<span>-&gt;</span>opt;
        } <span>else</span> {
            syslog(LOG_ERR, <span>"too many authentication options"</span>);
            <span>goto</span> fail;
        }
    }
    <span>while</span> (argc <span>&lt;</span> Nargc <span>-</span> <span>1</span> <span>&amp;&amp;</span> (argv[argc] <span>=</span> _auth_next_arg(as)))
        <span>++</span>argc;

    <span>if</span> (argc <span>&gt;=</span> Nargc <span>-</span> <span>1</span> <span>&amp;&amp;</span> _auth_next_arg(as)) {
        <span>if</span> (memcmp(<span>&amp;</span>nilap, <span>&amp;</span>(as<span>-&gt;</span>ap0), <span>sizeof</span>(nilap)) <span>!=</span> <span>0</span>) {
            va_end(as<span>-&gt;</span>ap0);
            explicit_bzero(<span>&amp;</span>(as<span>-&gt;</span>ap0), <span>sizeof</span>(as<span>-&gt;</span>ap0));
        }
        <span>if</span> (memcmp(<span>&amp;</span>nilap, <span>&amp;</span>(as<span>-&gt;</span>ap), <span>sizeof</span>(nilap)) <span>!=</span> <span>0</span>) {
            va_end(as<span>-&gt;</span>ap);
            explicit_bzero(<span>&amp;</span>(as<span>-&gt;</span>ap), <span>sizeof</span>(as<span>-&gt;</span>ap));
        }
        syslog(LOG_ERR, <span>"too many arguments"</span>);
        <span>goto</span> fail;
    }

    argv[argc] <span>=</span> NULL;

    <span>if</span> (socketpair(PF_LOCAL, SOCK_STREAM, <span>0</span>, pfd) <span>==</span> <span>-</span><span>1</span>) {
        syslog(LOG_ERR, <span>"unable to create backchannel %m"</span>);
        warnx(<span>"internal resource failure"</span>);
        <span>goto</span> fail;
    }

    <span>switch</span> (pid <span>=</span> fork()) {
    <span>case</span> <span>-</span><span>1</span><span>:</span>
        syslog(LOG_ERR, <span>"%s: %m"</span>, path);
        warnx(<span>"internal resource failure"</span>);
        close(pfd[<span>0</span>]);
        close(pfd[<span>1</span>]);
        <span>goto</span> fail;
    <span>case</span> <span>0</span><span>:</span>
<span>#define	COMM_FD	3
</span><span>#define	AUTH_FD	4
</span><span></span>        <span>if</span> (dup2(pfd[<span>1</span>], COMM_FD) <span>==</span> <span>-</span><span>1</span>)
            err(<span>1</span>, <span>"dup of backchannel"</span>);
        <span>if</span> (as<span>-&gt;</span>fd <span>!=</span> <span>-</span><span>1</span>) {
            <span>if</span> (dup2(as<span>-&gt;</span>fd, AUTH_FD) <span>==</span> <span>-</span><span>1</span>)
                err(<span>1</span>, <span>"dup of auth fd"</span>);
            closefrom(AUTH_FD <span>+</span> <span>1</span>);
        } <span>else</span>
            closefrom(COMM_FD <span>+</span> <span>1</span>);
        execve(path, argv, auth_environ);
        syslog(LOG_ERR, <span>"%s: %m"</span>, path);
        err(<span>1</span>, <span>"%s"</span>, path);
    <span>default</span><span>:</span>
        close(pfd[<span>1</span>]);
        <span>if</span> (as<span>-&gt;</span>fd <span>!=</span> <span>-</span><span>1</span>) {
            close(as<span>-&gt;</span>fd);		<span>/* so child has only ref */</span>
            as<span>-&gt;</span>fd <span>=</span> <span>-</span><span>1</span>;
        }
        <span>while</span> ((data <span>=</span> as<span>-&gt;</span>data) <span>!=</span> NULL) {
            as<span>-&gt;</span>data <span>=</span> data<span>-&gt;</span>next;
            <span>if</span> (data<span>-&gt;</span>len <span>&gt;</span> <span>0</span>) {
                write(pfd[<span>0</span>], data<span>-&gt;</span>ptr, data<span>-&gt;</span>len);
                explicit_bzero(data<span>-&gt;</span>ptr, data<span>-&gt;</span>len);
            }
            free(data);
        }
        as<span>-&gt;</span>index <span>=</span> <span>0</span>;
        _auth_spool(as, pfd[<span>0</span>]);
        close(pfd[<span>0</span>]);
        <span>do</span> {
            <span>if</span> (waitpid(pid, <span>&amp;</span>status, <span>0</span>) <span>!=</span> <span>-</span><span>1</span>) {
                <span>if</span> (<span>!</span>WIFEXITED(status))
                    <span>goto</span> fail;
                <span>break</span>;
            }
            <span>/*
</span><span>             ,* could get ECHILD if it was waited for by
</span><span>             ,* another thread or from a signal handler
</span><span>             ,*/</span>
        } <span>while</span> (errno <span>==</span> EINTR);
    }

    <span>/*
</span><span>     ,* Now scan the spooled data
</span><span>     ,* It is easier to wait for all the data before starting
</span><span>     ,* to scan it.
</span><span>     ,*/</span>
        <span>for</span> (line <span>=</span> as<span>-&gt;</span>spool; line <span>&lt;</span> as<span>-&gt;</span>spool <span>+</span> as<span>-&gt;</span>index;) {
        <span>if</span> (<span>!</span>strncasecmp(line, BI_REJECT, <span>sizeof</span>(BI_REJECT)<span>-</span><span>1</span>)) {
            line <span>+=</span> <span>sizeof</span>(BI_REJECT) <span>-</span> <span>1</span>;
            <span>if</span> (<span>!*</span>line <span>||</span> <span>*</span>line <span>==</span> <span>' '</span> <span>||</span> <span>*</span>line <span>==</span> <span>'\t'</span>) {
                <span>while</span> (<span>*</span>line <span>==</span> <span>' '</span> <span>||</span> <span>*</span>line <span>==</span> <span>'\t'</span>)
                    <span>++</span>line;
                <span>if</span> (<span>!</span>strcasecmp(line, <span>"silent"</span>)) {
                    as<span>-&gt;</span>state <span>=</span> AUTH_SILENT;
                    <span>break</span>;
                }
                <span>if</span> (<span>!</span>strcasecmp(line, <span>"challenge"</span>)) {
                    as<span>-&gt;</span>state  <span>=</span> AUTH_CHALLENGE;
                    <span>break</span>;
                }
                <span>if</span> (<span>!</span>strcasecmp(line, <span>"expired"</span>)) {
                    as<span>-&gt;</span>state  <span>=</span> AUTH_EXPIRED;
                    <span>break</span>;
                }
                <span>if</span> (<span>!</span>strcasecmp(line, <span>"pwexpired"</span>)) {
                    as<span>-&gt;</span>state  <span>=</span> AUTH_PWEXPIRED;
                    <span>break</span>;
                }
            }
            <span>break</span>;
        } <span>else</span> <span>if</span> (<span>!</span>strncasecmp(line, BI_AUTH, <span>sizeof</span>(BI_AUTH)<span>-</span><span>1</span>)) {
            line <span>+=</span> <span>sizeof</span>(BI_AUTH) <span>-</span> <span>1</span>;
            <span>if</span> (<span>!*</span>line <span>||</span> <span>*</span>line <span>==</span> <span>' '</span> <span>||</span> <span>*</span>line <span>==</span> <span>'\t'</span>) {
                <span>while</span> (<span>*</span>line <span>==</span> <span>' '</span> <span>||</span> <span>*</span>line <span>==</span> <span>'\t'</span>)
                    <span>++</span>line;
                <span>if</span> (<span>*</span>line <span>==</span> <span>'\0'</span>)
                    as<span>-&gt;</span>state <span>|=</span> AUTH_OKAY;
                <span>else</span> <span>if</span> (<span>!</span>strcasecmp(line, <span>"root"</span>))
                    as<span>-&gt;</span>state <span>|=</span> AUTH_ROOTOKAY;
                <span>else</span> <span>if</span> (<span>!</span>strcasecmp(line, <span>"secure"</span>))
                    as<span>-&gt;</span>state <span>|=</span> AUTH_SECURE;
            }
        } <span>else</span> <span>if</span> (<span>!</span>strncasecmp(line, BI_REMOVE, <span>sizeof</span>(BI_REMOVE)<span>-</span><span>1</span>)) {
            line <span>+=</span> <span>sizeof</span>(BI_REMOVE) <span>-</span> <span>1</span>;
            <span>while</span> (<span>*</span>line <span>==</span> <span>' '</span> <span>||</span> <span>*</span>line <span>==</span> <span>'\t'</span>)
                <span>++</span>line;
            <span>if</span> (<span>*</span>line)
                _add_rmlist(as, line);
        }
        <span>while</span> (<span>*</span>line<span>++</span>)
            ;
    }

    <span>if</span> (WEXITSTATUS(status))
        as<span>-&gt;</span>state <span>&amp;=</span> <span>~</span>AUTH_ALLOW;

    okay <span>=</span> as<span>-&gt;</span>state <span>&amp;</span> AUTH_ALLOW;

    <span>if</span> (<span>!</span>okay)
        auth_clrenv(as);

    <span>if</span> (<span>0</span>) {
fail:
        auth_clrenv(as);
        as<span>-&gt;</span>state <span>=</span> <span>0</span>;
        okay <span>=</span> <span>-</span><span>1</span>;
    }

    <span>while</span> ((data <span>=</span> as<span>-&gt;</span>data) <span>!=</span> NULL) {
        as<span>-&gt;</span>data <span>=</span> data<span>-&gt;</span>next;
        free(data);
    }

    <span>if</span> (memcmp(<span>&amp;</span>nilap, <span>&amp;</span>(as<span>-&gt;</span>ap0), <span>sizeof</span>(nilap)) <span>!=</span> <span>0</span>) {
        va_end(as<span>-&gt;</span>ap0);
        explicit_bzero(<span>&amp;</span>(as<span>-&gt;</span>ap0), <span>sizeof</span>(as<span>-&gt;</span>ap0));
    }

    <span>if</span> (memcmp(<span>&amp;</span>nilap, <span>&amp;</span>(as<span>-&gt;</span>ap), <span>sizeof</span>(nilap)) <span>!=</span> <span>0</span>) {
        va_end(as<span>-&gt;</span>ap);
        explicit_bzero(<span>&amp;</span>(as<span>-&gt;</span>ap), <span>sizeof</span>(as<span>-&gt;</span>ap));
    }
    <span>return</span> (okay);
}</code></pre></div>
</div>
</details>
<p>
  <a href="https://man.openbsd.org/auth_subr.3#auth_call~2"><code>auth_call</code></a> is responsible for setting up the environment,
  calling the modules, and communicating with them.</p>
<p>
  An array of char pointers called <code>argv</code> is allocated to hold the arguments for the
  auth module.</p>
<div>
<div><pre><code data-lang="c"><span>char</span> <span>*</span>argv[<span>64</span>];		<span>/* 64 args should be more than enough */</span></code></pre></div>
</div>
<p>
  First, the variable arguments are placed in <code>as-&gt;ap0</code>.</p>
<p>
  <a href="#_auth_next_arg"><code>_auth_next_arg</code></a> is called once, with the result being set as the
  first element in <code>argv</code>. If <code>as-&gt;fd</code> is set, adds <code>-v</code> and <code>fd=4</code> to
  <code>argv</code>.</p>
<p>
  Then it loops through the <code>optlist</code> and appends <code>-v</code> followed the
  option for each of them.</p>
<p>
  After that the rest of the arguments are retrieved from
  <code>_auth_next_arg</code> and added to the end of <code>argv</code>. Finally a <code>NULL</code> is
  added to the end of <code>argv</code>.</p>
<p>
  Next a socket pair of type <code>PF_LOCAL, SOCK_STREAM</code> is created. This
  is called the "back channel", and is used to communicate with the
  authentication module.</p>
<p>
  The process then calls <a href="https://man.openbsd.org/man2/fork.2"><code>fork(2)</code></a>.</p>
<p>
  Here two constants are set for the back channel and optional
  authentication file descriptors.</p>
<div>
<div><pre><code data-lang="c"><span>#define	COMM_FD	3
</span><span>#define	AUTH_FD	4</span></code></pre></div>
</div>
<p>
  In the child process, the back channel is set to file descriptor 3,
  or <code>COMM_FD</code> using <a href="https://man.openbsd.org/man2/dup.2#dup2"><code>dup2(3)</code></a>. If <code>as-&gt;fd</code>, is not <code>-1</code>, it is set to
  file descriptor 4, or <code>AUTH_FD</code>, also using <code>dup2(3)</code>. The remainder
  of the file descriptors are closed using <a href="https://man.openbsd.org/man2/closefrom.2"><code>closefrom(2)</code></a> by calling
  either <code>closefrom(COMM_FD + 1)</code> or <code>closefrom(AUTH_FD + 1)</code>,
  depending on whether or not <code>AUTH_FD</code> is used.</p>
<p>
  The child process then executes the module.</p>
<div>
<div><pre><code data-lang="c">execve(path, argv, auth_environ);</code></pre></div>
</div>
<p>
  <code>auth_environ</code> is defined at the top of the file as a very minimal
  environment.</p>
<div>
<div><pre><code data-lang="c"><span>static</span> <span>char</span> <span>*</span>auth_environ[] <span>=</span> {
    <span>"PATH="</span> _PATH_DEFPATH,
    <span>"SHELL="</span> _PATH_BSHELL,
    NULL,
};</code></pre></div>
</div>
<p>
  Where both constants are defined in <code>/include/paths.h</code>.</p>
<div>
<div><pre><code data-lang="c"><span>#define	_PATH_DEFPATH	"/usr/bin:/bin:/usr/sbin:/sbin:/usr/X11R6/bin:/usr/local/bin:/usr/local/sbin"
</span><span>#define	_PATH_BSHELL	"/bin/sh"</span></code></pre></div>
</div>
<p>
  In the parent process, the child's end of the back channel is
  closed, and so is the parent's copy of <code>as-&gt;fd</code> if it exists.</p>
<p>
  The data from <code>as-&gt;data</code> is then written to the back channel
  sequentially, zeroed, and freed.</p>
<p>
  Next <code>as-&gt;index</code> is set to <code>0</code>.</p>
<p>
  The response from the authentication module is then read from the
  back channel and put into <code>as-&gt;spool</code> with an optional received file
  descriptor placed in <code>as-&gt;fd</code>, using <a href="#_auth_spool"><code>_auth_spool</code></a>.</p>

<p>
  Once the back channel data has finished spooling, it is scanned for
  key words defined in <code>login_cap.h</code>.</p>
<div>
<div><pre><code data-lang="c"><span>#define BI_AUTH         "authorize"         </span><span>/* Accepted authentication */</span><span>
</span><span>#define BI_REJECT       "reject"            </span><span>/* Rejected authentication */</span><span>
</span><span>#define BI_CHALLENGE    "reject challenge"  </span><span>/* Reject with a challenge */</span><span>
</span><span>#define BI_SILENT       "reject silent"     </span><span>/* Reject silently */</span><span>
</span><span>#define BI_REMOVE       "remove"            </span><span>/* remove file on error */</span><span>
</span><span>#define BI_ROOTOKAY     "authorize root"    </span><span>/* root authenticated */</span><span>
</span><span>#define BI_SECURE       "authorize secure"  </span><span>/* okay on non-secure line */</span><span>
</span><span>#define BI_SETENV       "setenv"            </span><span>/* set environment variable */</span><span>
</span><span>#define BI_UNSETENV     "unsetenv"          </span><span>/* unset environment variable */</span><span>
</span><span>#define BI_VALUE        "value"             </span><span>/* set local variable */</span><span>
</span><span>#define BI_EXPIRED      "reject expired"    </span><span>/* account expired */</span><span>
</span><span>#define BI_PWEXPIRED    "reject pwexpired"  </span><span>/* password expired */</span><span>
</span><span>#define BI_FDPASS       "fd"                </span><span>/* child is passing an fd */</span></code></pre></div>
</div>
<p>
  The <a href="https://man.openbsd.org/login.conf"><code>login.conf(5)</code></a> man page once again goes into greater detail on
  these values.</p>
<div>
<div><pre><code data-lang="text">authorize  The user has been authorized.

authorize secure
           The user has been authorized and root should be allowed to
           login even if this is not a secure terminal.  This should only
           be sent by authentication styles that are secure over insecure
           lines.

reject     Authorization is rejected.  This overrides any indication that
           the user was authorized (though one would question the wisdom
           in sending both a reject and an authorize command).

reject challenge
           Authorization was rejected and a challenge has been made
           available via the value challenge.

reject silent
           Authorization is rejected, but no error messages should be
           generated.

remove file
           If the login session fails for any reason, remove file before
           termination.

setenv name value
           If the login session succeeds, …</code></pre></div></div></div></div>
